script.setup:
// NetworkX laid out the Les Misérables character network and found its communities on this
// computer (recipe networkx.les-miserables-layout → graph.json). Hover a character.
const data = await (await fetch(ctx.assets["graph.json"])).json();
const gl = ctx.gl;
const buffer = (n) => {
  const vao = gl.createVertexArray(), b = gl.createBuffer();
  gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, b);
  gl.bufferData(gl.ARRAY_BUFFER, n * 16, gl.DYNAMIC_DRAW);
  gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 16, 0);
  gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 16, 8);
  gl.bindVertexArray(null);
  return { vao, b, data: new Float32Array(n * 4) };
};
Object.assign(ctx.state, { data, edges: buffer(data.edges.length * 2), nodes: buffer(data.nodes.length), xy: new Float32Array(data.nodes.length * 2),
  p: ctx.utils.createProgram("#version 300 es\nlayout(location=0) in vec2 a_position; layout(location=1) in vec2 a_info;\nuniform vec2 u_fit; out vec2 v_info;\nvoid main(){ v_info = a_info; gl_Position = vec4((a_position * 2.0 - 1.0) * u_fit, 0.0, 1.0); gl_PointSize = a_info.y; }", "#version 300 es\nprecision highp float; in vec2 v_info; out vec4 outColor; uniform int u_mode; uniform vec3 u_palette[8];\nvoid main(){\n  if (u_mode == 0) { outColor = vec4(vec3(0.5, 0.55, 0.7) * v_info.x, 1.0); return; }\n  float d = length(gl_PointCoord - 0.5); if (d > 0.5) discard;\n  vec3 c = u_palette[int(v_info.x) % 8];\n  outColor = vec4(c * (smoothstep(0.5, 0.35, d) + 0.25), 1.0);\n}"),
  palette: [[1, 0.45, 0.35], [0.35, 0.75, 1], [0.95, 0.8, 0.3], [0.55, 0.9, 0.5], [0.85, 0.5, 1], [1, 0.6, 0.8], [0.4, 0.95, 0.85], [0.9, 0.9, 0.9]].flat() });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution, d = s.data;
const view = w / h, fit = view > 1 ? [0.95 / view, 0.95] : [0.95, 0.95 * view];
const t = ctx.time * u.u_motion;
d.nodes.forEach((n, i) => {
  s.xy[i * 2] = n.x + 0.006 * Math.sin(t + i * 1.7);
  s.xy[i * 2 + 1] = n.y + 0.006 * Math.cos(t * 0.9 + i * 2.3);
});
// The character under the pointer (screen → layout space).
const mx = ((ctx.mouse[0] * 2 - 1) / fit[0] + 1) / 2, my = (((1 - ctx.mouse[1]) * 2 - 1) / fit[1] + 1) / 2;
// The pointer starts at the center; hovering begins once it has moved.
s.moved ||= ctx.mouse[0] !== 0.5 || ctx.mouse[1] !== 0.5;
let hover = -1, best = s.moved ? 0.0009 : 0;
d.nodes.forEach((_, i) => { const dd = (s.xy[i * 2] - mx) ** 2 + (s.xy[i * 2 + 1] - my) ** 2; if (dd < best) { best = dd; hover = i; } });
const dpr = Math.min(2, devicePixelRatio);
d.edges.forEach(([a, b, wgt], k) => {
  const lit = hover < 0 ? 0.9 + Math.min(wgt, 10) * 0.12 : a === hover || b === hover ? 1.6 : 0.12;
  s.edges.data.set([s.xy[a * 2], s.xy[a * 2 + 1], lit, 0, s.xy[b * 2], s.xy[b * 2 + 1], lit, 0], k * 8);
});
d.nodes.forEach((n, i) => s.nodes.data.set([s.xy[i * 2], s.xy[i * 2 + 1], n.group, (5 + Math.sqrt(n.degree) * 3.2 * u.u_size) * dpr * (i === hover ? 1.6 : 1)], i * 4));
gl.clearColor(0.03, 0.03, 0.045, 1); gl.clear(gl.COLOR_BUFFER_BIT);
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
gl.useProgram(s.p);
ctx.utils.setUniforms(s.p, { u_fit: fit, u_palette: s.palette, u_mode: 0 });
for (const [part, mode, prim] of [[s.edges, 0, gl.LINES], [s.nodes, 1, gl.POINTS]]) {
  ctx.utils.setUniforms(s.p, { u_mode: mode });
  gl.bindVertexArray(part.vao); gl.bindBuffer(gl.ARRAY_BUFFER, part.b);
  gl.bufferSubData(gl.ARRAY_BUFFER, 0, part.data);
  gl.drawArrays(prim, 0, part.data.length / 4);
}
gl.bindVertexArray(null); gl.disable(gl.BLEND);
ctx.publish("character", hover >= 0 ? d.nodes[hover].name : "—");
